{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_stack",
        "hero_image",
        "intro_text",
        "eligibility_card",
        "financial_card",
        "email_card",
        "quick_actions_stack"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "title",
        "header_icon"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Product Returns Procedure",
        "variant": "h1"
      },
      "children": []
    },
    "header_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/shop.svg"
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Seattle_Skyline_from_Kerry_Park.jpg/1200px-Seattle_Skyline_from_Kerry_Park.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Standard operating procedure for processing electronics returns at Northwest Tech Gear, Seattle. Policy updated: 2023-11-01."
      },
      "children": []
    },
    "eligibility_card": {
      "type": "Card",
      "props": {},
      "children": [
        "eligibility_title",
        "eligibility_list"
      ]
    },
    "eligibility_title": {
      "type": "Text",
      "props": {
        "text": "Return Eligibility & Inspection",
        "variant": "h2"
      },
      "children": []
    },
    "eligibility_list": {
      "type": "List",
      "props": {},
      "children": [
        "eligibility_item_1",
        "eligibility_item_2",
        "eligibility_item_3",
        "eligibility_item_4"
      ]
    },
    "eligibility_item_1": {
      "type": "Text",
      "props": {
        "text": "Window Verification: Confirm the purchase date is within the last 30 calendar days."
      },
      "children": []
    },
    "eligibility_item_2": {
      "type": "Text",
      "props": {
        "text": "Packaging Check: Ensure the item is in its original box with all accessories included."
      },
      "children": []
    },
    "eligibility_item_3": {
      "type": "Text",
      "props": {
        "text": "Serial Number Match: Verify that the device serial number matches the receipt and box labels."
      },
      "children": []
    },
    "eligibility_item_4": {
      "type": "Text",
      "props": {
        "text": "Physical Condition: Inspect for water damage, cracked screens, or unauthorized repairs."
      },
      "children": []
    },
    "financial_card": {
      "type": "Card",
      "props": {},
      "children": [
        "financial_title",
        "financial_list"
      ]
    },
    "financial_title": {
      "type": "Text",
      "props": {
        "text": "Financial & Logistics Processing",
        "variant": "h2"
      },
      "children": []
    },
    "financial_list": {
      "type": "List",
      "props": {},
      "children": [
        "financial_item_1",
        "financial_item_2",
        "financial_item_3",
        "financial_item_4"
      ]
    },
    "financial_item_1": {
      "type": "Text",
      "props": {
        "text": "Defect Returns: Process a 100% refund to the original payment method for verified hardware failures."
      },
      "children": []
    },
    "financial_item_2": {
      "type": "Text",
      "props": {
        "text": "Change of Mind: Apply a 15% restocking fee; the remaining 85% is refunded to the customer."
      },
      "children": []
    },
    "financial_item_3": {
      "type": "Text",
      "props": {
        "text": "In-Store Returns: Process immediately at the service desk and move item to 'Restock' or 'RMA' bin."
      },
      "children": []
    },
    "financial_item_4": {
      "type": "Text",
      "props": {
        "text": "Mail-in Returns: Log the tracking number, inspect within 48 hours of arrival, and trigger the digital refund."
      },
      "children": []
    },
    "email_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email_card_title",
        "email_subject_label",
        "email_subject_text",
        "email_body_stack",
        "email_signature_stack"
      ]
    },
    "email_card_title": {
      "type": "Text",
      "props": {
        "text": "Customer Notification Template",
        "variant": "h2"
      },
      "children": []
    },
    "email_subject_label": {
      "type": "Text",
      "props": {
        "text": "Subject:",
        "variant": "label"
      },
      "children": []
    },
    "email_subject_text": {
      "type": "Text",
      "props": {
        "text": "Your Refund from Northwest Tech Gear - Order #[OrderNumber]",
        "variant": "body"
      },
      "children": []
    },
    "email_body_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email_body_para1",
        "email_body_para2"
      ]
    },
    "email_body_para1": {
      "type": "Text",
      "props": {
        "text": "Dear [Customer Name],"
      },
      "children": []
    },
    "email_body_para2": {
      "type": "Text",
      "props": {
        "text": "This is to notify you that we have successfully processed your return for [Product Name]. A refund of [Amount] has been issued to your original payment method. Please allow 3-5 business days for the credit to appear on your statement."
      },
      "children": []
    },
    "email_signature_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "email_signature_line1",
        "email_signature_line2"
      ]
    },
    "email_signature_line1": {
      "type": "Text",
      "props": {
        "text": "Best regards,"
      },
      "children": []
    },
    "email_signature_line2": {
      "type": "Text",
      "props": {
        "text": "Northwest Tech Gear Support"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "center"
      },
      "children": [
        "return_portal_button",
        "internal_dashboard_button"
      ]
    },
    "return_portal_button": {
      "type": "Button",
      "props": {
        "label": "Return Portal"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://nwtechgear.com/returns"
          }
        }
      },
      "children": []
    },
    "internal_dashboard_button": {
      "type": "Button",
      "props": {
        "label": "Internal Dashboard"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://internal.nwtechgear.com/pos"
          }
        }
      },
      "children": []
    }
  }
}
